  'blog.empty': 'வலைப்பதிவு பதிவுகள் எதுவும் இல்லை',
  'blog.visitBlog': 'வலைப்பதிவு வலைத்தளத்தைப் பார்வையிடுங்கள்',
  'blog.stayUpdated': 'எங்கள் சமீபத்திய பதிவுகளுடன் அப்டேட்டாக இருக்க விரும்புகிறீர்களா?',
