  'feat.f3d': "Greeks, ஓபன் இன்ட்ரெஸ்ட், வால்யூம், பிட்/ஆஸ்க் ஆகியவற்றுடன் நேரடி ஆப்ஷன் செயின் - எந்த ஸ்ட்ரைக்கிலும் கிளிக் செய்து உடனே டிரேட் செய்யுங்கள்",
