  'feat.f4d': "at-the-money ஸ்ட்ரைக்கிற்கு IV, Delta, Theta, Vega, Gamma ஆகியவை காலப்போக்கில் எப்படி நகர்ந்தன என்பதைப் பாருங்கள்",
