  'feat.f7d': "எக்ஸ்பயரியில் விலை எங்கு செட்டில் ஆகும் வாய்ப்பு அதிகம் என்பதை, அனைத்து ஸ்ட்ரைக்குகளிலும் காட்சிப்படுத்தி காட்டுகிறது",
