  'feat.f44t': "நிகழ்நேர PnL ட்ராக்கர்",
  'feat.f44d': "நேரடி P&L கர்வ், ட்ராடவுன், வின் ரேட், ஸ்ட்ராடஜி வாரியான பிரிவு - உங்கள் நாள் எப்படி போகிறது என்பதைச் சரியாகப் பாருங்கள்",
  'feat.f45t': "லேட்டன்சி மானிட்டர்",
  'feat.f45d': "உங்கள் ஆர்டர்கள் உண்மையில் எத்தனை மில்லிசெகண்ட்கள் எடுக்கின்றன என்பதைப் பாருங்கள் - ப்ரோக்கர்களை பக்கத்திற்குப் பக்கமாக ஒப்பிட்டு, செலவாகும் முன் மெதுவான இணைப்புகளைக் கண்டறியுங்கள்",
  'feat.f46t': "ட்ராஃபிக் லாக்குகள்",
  'feat.f46d': "நீங்கள் செய்யும் ஒவ்வொரு API காலும் லாக் செய்யப்படுகிறது - சோர்ஸ், ஸ்டேட்டஸ், அல்லது எண்ட்பாயிண்ட் அடிப்படையில் ஃபில்டர் செய்து ஆடிட் அல்லது டிபகிங்கிற்காக CSV-ஆக எக்ஸ்போர்ட் செய்யுங்கள்",
  'feat.f47t': "ஆடிட் ட்ரெயில்",
  'feat.f47d': "ஒவ்வொரு ஆர்டர், லாகின், கான்ஃபிக் மாற்றத்தின் முழு டேட்டாபேஸ்-அடிப்படையிலான லாக் - ஏதேனும் தவறாகத் தோன்றினால் ஆதாரங்களைக் கொண்டு வாருங்கள்",
