  'feat.f50d': "ஒவ்வொரு ப்ரோக்கருக்கும் ஒரே நார்மலைஸ் செய்யப்பட்ட நிகழ்நேர ஃபீட் - டேட்டா யாரிடமிருந்து வருகிறது என்பதை உங்கள் கோட் ஒருபோதும் கவலைப்பட வேண்டியதில்லை",
  'feat.f51t': "Raw WebSocket இம்ப்ளிமெண்டேஷன்",
  'feat.f51d': "ப்ரோக்கர் WebSocket-களில் நேரடியாகக் கட்டப்பட்டது (மூன்றாம் தரப்பு SDK-கள் இல்லை) - குறைந்த லேட்டன்சி, குறைவான இடைநிலை லேயர்கள், அதிக நம்பகத்தன்மை",
  'feat.f52t': "ஆட்டோ-ரீகனெக்ஷன்",
  'feat.f52d': "ஒரு ப்ரோக்கர் ஃபீட் துண்டானால், OpenAlgo உங்களுக்காக மீண்டும் இணைத்து மீண்டும் சப்ஸ்கிரைப் செய்யும் - கண்காணிக்க வேண்டியதில்லை",
