  'skill.cat8e': "Crossover, Highest, Lowest, Rising",
  'skill.tryTitle': "இவற்றை உங்கள் AI-இல் முயற்சிக்கவும்",
  'skill.ie1': "15-நிமிட NIFTY-இல் Supertrend சார்ட் செய்யுங்கள்",
  'skill.ie2': "RELIANCE-இல் டெய்லி RSI-ஐ ப்ளாட் செய்யுங்கள்",
  'skill.ie3': "Z-Score இண்டிகேட்டரை பூஜ்ஜியத்திலிருந்து உருவாக்குங்கள்",
  'skill.ie4': "SBIN-க்கான multi-timeframe டாஷ்போர்டு",
  'skill.ie5': "Oversold பங்குகளுக்காக NIFTY 50-ஐ ஸ்கேன் செய்யுங்கள்",
  'skill.ie6': "இண்டிகேட்டர்களுடன் நேரடி NIFTY விலைகளை ஸ்ட்ரீம் செய்யுங்கள்",
  'skill.btTitle': "பேக்டெஸ்டிங் Skills",
  'skill.btDesc': "உண்மையான கடந்தகால டேட்டாவில் டிரேடிங் ஐடியாக்களைச் சோதிக்கவும். இந்திய, US மற்றும் கிரிப்டோ சந்தைகளுக்கான கட்டணங்கள், வரிகள் மற்றும் ஸ்லிப்பேஜ் ஏற்கனவே சேர்க்கப்பட்டுள்ளன - எனவே முடிவுகள் உங்கள் கணக்கில் நீங்கள் உண்மையில் பார்க்கும் அளவைப் பிரதிபலிக்கின்றன.",
  'skill.bc1t': "முதல் முறை செட்அப்",
  'skill.bc1d': "உங்கள் மெஷினில் பேக்டெஸ்ட்களை இயக்க தேவையான அனைத்தையும் தயார்படுத்துகிறது. ஒருமுறை இயக்குங்கள்.",
  'skill.bc2t': "ஒரு ஸ்ட்ராடஜியை பேக்டெஸ்ட் செய்யுங்கள்",
  'skill.bc2d': "யதார்த்தமான ப்ரோக்கரேஜ் மற்றும் வரிகளுடன் எந்த ஸ்ட்ராடஜியையும் கடந்தகால டேட்டாவில் இயக்குங்கள். எளிய மொழியில் ஒரு முழுமையான ரிப்போர்ட்டையும், ஒரு தொழில்முறை-தர PDF-பாணி tearsheet-ஐயும் பெறுங்கள்.",
  'skill.bc3t': "சிறந்த செட்டிங்குகளைக் கண்டறியுங்கள்",
  'skill.bc3d': "ஒரு ஸ்ட்ராடஜியின் செட்டிங்குகளின் பல சேர்க்கைகளைச் சோதித்து, ஒரு காட்சி ஹீட்மேப்பில் சிறந்தவற்றை சிறப்பித்துக் காட்டுங்கள்.",
  'skill.bc4t': "விரைவான சானிட்டி செக்",
  'skill.bc4d': "ஒரு ஸ்ட்ராடஜியின் ரிட்டர்ன், ட்ராடவுன், மற்றும் அது இண்டெக்ஸுடன் எப்படி ஒப்பிடுகிறது என்பதன் விரைவான வாசிப்பு - கோப்புகள் எதுவும் உருவாக்கப்படாது.",
  'skill.bc5t': "ஸ்ட்ராடஜிகளை ஒப்பிடுங்கள்",
  'skill.bc5d': "ஒரே பங்கில் இரண்டு அல்லது அதற்கு மேற்பட்ட ஸ்ட்ராடஜிகளை இயக்கி, அவற்றின் எக்விட்டி கர்வ்களை பக்கத்திற்குப் பக்கம் வையுங்கள்.",
  'skill.stratTitle': "12 தயார் நிலை ஸ்ட்ராடஜிகள்",
  'skill.stratSub': "வேலை செய்யும் ஒரு ஸ்ட்ராடஜியுடன் தொடங்கி, அதை உங்கள் பாணிக்கு ஏற்ப மாற்றியமையுங்கள் - பூஜ்ஜியத்திலிருந்து உருவாக்குவதை விட வேகமானது.",
