  'skill.feesTitle': "நிஜ-உலக கட்டணங்கள் உள்ளடங்கியவை",
  'skill.feesSub': "எண்கள் யதார்த்தத்தைப் பிரதிபலிக்கும் வகையில் பேக்டெஸ்ட்கள் உண்மையான ப்ரோக்கரேஜ், வரிகள் மற்றும் ஸ்லிப்பேஜைப் பயன்படுத்துகின்றன. ப்ரோக்கரை மாற்றுகிறீர்களா? ஒரு வரியை புதுப்பியுங்கள்.",
