  'skill.marketsTitle': "உள்ளடக்கப்பட்ட சந்தைகள்",
  'skill.marketsSub': "நீங்கள் இந்திய சந்தைகள், US பங்குகள், அல்லது கிரிப்டோ - எதைத் டிரேட் செய்தாலும், அதே கமாண்டுகள் வேலை செய்யும். சிம்பலின் அடிப்படையில் உங்கள் AI சரியான டேட்டா சோர்ஸைத் தேர்ந்தெடுக்கும்.",
