  // WABridge page
  'wab.badgeOpenSource': "ஓப்பன் சோர்ஸ்",
  'wab.heroTag': "ஒரு லைட்வெயிட் WhatsApp HTTP பிரிட்ஜ்.",
  'wab.heroDesc': "CLI மூலம் உங்கள் WhatsApp-ஐ இணைக்கவும், பிறகு ஒரு எளிய REST API மூலம் மெசேஜ்களை அனுப்பவும். டெக்ஸ்ட், படங்கள், வீடியோ, ஆடியோ, ஆவணங்களை ஆதரிக்கிறது - தனிநபர்கள், குழுக்கள், மற்றும் சேனல்களுக்கு.",
  'wab.orRun': "அல்லது நேரடியாக இயக்கவும்:",
  'wab.ctaNode': "Node.js CLI",
  'wab.ctaPython': "Python SDK",
  'wab.howTitle': "இது எப்படி வேலை செய்கிறது",
  'wab.howDesc': "WABridge உங்கள் ஆப்ளிகேஷன்களுக்கும் WhatsApp-க்கும் இடையில் அமர்ந்து, ஒரு உள்ளூர் HTTP சர்வர் மூலம் மெசேஜ்களை அனுப்புகிறது.",
  'wab.howCaption': "உங்கள் ஆப் WABridge-க்கு HTTP ரிக்வெஸ்ட்களை அனுப்புகிறது, அது அவற்றை WhatsApp-க்கு டெலிவர் செய்கிறது.",
  'wab.f1t': "எளிய REST API",
  'wab.f1d': "ஒரு மெசேஜை அனுப்ப ஒரே ஒரு POST ரிக்வெஸ்ட். சிக்கலான SDK-க்களோ auth ஃப்ளோக்களோ தேவையில்லை.",
  'wab.f2t': "ரிச் மீடியா",
  'wab.f2d': "படங்கள், வீடியோக்கள், voice notes, மற்றும் ஆவணங்களை அனுப்புங்கள். URL-களையும் உள்ளூர் கோப்பு பாத்களையும் ஆதரிக்கிறது.",
  'wab.f3t': "குழுக்கள் & சேனல்கள்",
  'wab.f3d': "தனிநபர்கள், குழுக்கள், மற்றும் சேனல்களுக்கு அனுப்புங்கள். குழுக்களை அவற்றின் JID-களுடன் ப்ரோகிராமேட்டிக்காக லிஸ்ட் செய்யுங்கள்.",
  'wab.f4t': "செல்ஃப்-ஹோஸ்டட்",
  'wab.f4d': "உங்கள் மெஷினில் இயங்குகிறது. மூன்றாம்-தரப்பு கிளவுட் சேவைகள் இல்லை. உங்கள் மெசேஜ்கள் உள்ளூரிலேயே இருக்கும்.",
  'wab.f5t': "Python SDK",
  'wab.f5d': "ஒரே ஃபங்க்ஷன் கால் மூலம் Python-லிருந்து மெசேஜ்களை அனுப்புங்கள். Sync மற்றும் async ஆதரவு உள்ளடங்கியுள்ளது.",
  'wab.f6t': "இன்டராக்டிவ் CLI",
  'wab.f6d': "டெர்மினலிலிருந்து இன்டராக்டிவ்வாக மெசேஜ்களைச் சோதிக்கவும். QR கோட் அல்லது பேரிங் கோட் மூலம் இணைக்கவும்.",
  'wab.qsTitle': "விரைவு தொடக்கம்",
  'wab.qs1t': "WhatsApp-ஐ இணைக்கவும்",
  'wab.qs1qr': "QR கோட் (டிஃபால்ட்):",
  'wab.qs1pair': "பேரிங் கோட் (மாற்று):",
  'wab.qs1auth1': "Auth சேமிக்கப்படும் இடம்",
  'wab.qs1auth2': "- நீங்கள் ஒருமுறை மட்டுமே இணைக்க வேண்டும்.",
  'wab.qs2t': "API சர்வரைத் தொடங்குங்கள்",
  'wab.qs2custom': "கஸ்டம் போர்ட்:",
  'wab.qs3t': "மெசேஜ்களை அனுப்புங்கள்",
  'wab.qs3curl': "curl பயன்படுத்தி:",
