  'wab.api1d': "WhatsApp இணைப்பு ஸ்டேட்டஸைச் சரிபார்",
  'wab.api2d': "அனைத்து WhatsApp குழுக்களையும் அவற்றின் JID-களுடன் லிஸ்ட் செய்",
  'wab.api3d': "டெக்ஸ்ட், படம், வீடியோ, ஆடியோ, அல்லது ஆவணத்தை அனுப்பு",
  'wab.api4d': "உங்களுக்கே ஒரு மெசேஜை அனுப்பு",
  'wab.api5d': "ஒரு WhatsApp குழுவிற்கு ஒரு மெசேஜை அனுப்பு",
  'wab.api6d': "ஒரு WhatsApp சேனலுக்கு ஒரு மெசேஜை அனுப்பு",
  'wab.fieldsTitle': "மெசேஜ் கன்டெண்ட் ஃபீல்டுகள்",
